export default class Helpers {

    /**
     * Returns a version of a project colour that stays visible on the dark overlay.
     * Very dark colours (relative luminance below ~0.12) are mixed 45% toward white.
     * Falls back to the site amber for anything that is not a 6-digit hex colour.
     */
    static readableAccent = (hex: string): string => {
        const m = /^#?([0-9a-f]{6})$/i.exec(hex || "");
        if (!m) {
            return "#c9962f";
        }
        const n = parseInt(m[1], 16);
        const linear = (c: number) => {
            const s = c / 255;
            return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
        };
        const lum = 0.2126 * linear((n >> 16) & 255) + 0.7152 * linear((n >> 8) & 255) + 0.0722 * linear(n & 255);
        if (lum >= 0.12) {
            return "#" + m[1];
        }
        // Near-black lifts to flat grey; use the site amber instead
        if (lum < 0.04) {
            return "#c9962f";
        }
        const lift = (c: number) => Math.round(c + (255 - c) * 0.45).toString(16).padStart(2, "0");
        return "#" + lift((n >> 16) & 255) + lift((n >> 8) & 255) + lift(n & 255);
    }

    static preloadImages = (urls: string[]) => {
        urls.forEach(url => {
            Helpers.preloadImage(url);
        });
    }

    private static preloadImage = (url: string) => {
        const image = new Image(); 
        image.src = url; 
    }

static getSketchfabThumbnail = (modelUID: string, project: { iconUrl: string }): string => {
  // Empty until the real thumbnail arrives, so no request is made for a missing placeholder image
  const placeholder = "";

  fetch(`https://sketchfab.com/v3/models/${modelUID}`)
    .then((res) => res.json())

    .then((data) => {
    const images = data?.thumbnails?.images as { width: number; url: string }[] | undefined;
    const best = images?.sort((a, b) => b.width - a.width)[0]?.url;
    if (best) {
            project.iconUrl = best;
            Helpers.preloadImage(best); // Optional: preload to avoid flicker
        }
    })
    
    .catch((err) => console.error("Error fetching Sketchfab thumbnail:", err));

  return placeholder;

  };
}
