
import Vue from "vue";

export default Vue.extend({
  name: "Header",
  data() {
    return {
      isCompact: false,
    };
  },
  mounted() {
    window.addEventListener("scroll", this.onScroll, { passive: true });
  },
  beforeDestroy() {
    window.removeEventListener("scroll", this.onScroll);
  },
  methods: {
    // Shrink the header once the page has scrolled past the top
    onScroll() {
      this.isCompact = window.scrollY > 80;
    },
  },
});
